char str[] = "Hi";
// strlen(str) == 2 (Excludes '\0')
// sizeof(str) == 3 (Includes '\0')

#include <stdio.h>
#include <string.h>

void reverse(char *str) {
    int i = 0, j = strlen(str) - 1;
    while (i < j) {
        char temp = str[i];
        str[i++] = str[j];
        str[j--] = temp;
    }
}

int main() {
    char s[] = "hello";
    reverse(s);
    printf("%s\n", s); // Output: olleh
}

